// EVERY QC AND HR RECORD GENERATED BY ITS FREQUENCY, MONTH AFTER MONTH, YEAR AFTER YEAR (REQUIREMENTS §236; the owner,
// 16-Nov-2026: "it will generate for next all month all year and will continue and in qc and hr there are many records
// are there so according to there frequency it should generate for next day, month, year, as there frequency"). The
// generator runs for each month as it comes (the server's morning prepare every working day, and every page that opens
// a month): here, December 2026 to December 2027, across the year's end. And a sheet due on a day the plant is closed
// stays in its own month (holidays.ts workingDueDate): F/HR/15's and F/HR/22's December sheet, due on the 31st, a
// Thursday, is December's.
// Run: npm run test:unit -- generationAhead
import test from "node:test";
import assert from "node:assert/strict";
import { documentRepository, ensureSeeded as ensureDocumentsSeeded } from "../src/data/repositories/documentRepository";
import { masterRepository, ensureSeeded as ensureMasterSeeded } from "../src/data/repositories/masterRepository";
import { recordRepository } from "../src/data/repositories/recordRepository";
import { ensureRecordsGeneratedForMonth } from "../src/engine/recordGenerator";
import { departmentOfDocument } from "../src/data/seed/documentDepartments";
import { workingDueDate } from "../src/engine/holidays";

ensureDocumentsSeeded();
ensureMasterSeeded();

const MONTHS: [number, number][] = [[2026, 11], ...Array.from({ length: 12 }, (_, m) => [2027, m] as [number, number])];
const ym = (y: number, m: number) => `${y}-${String(m + 1).padStart(2, "0")}`;
const daysIn = (y: number, m: number) => new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
const weekdaysIn = (y: number, m: number, wd: number) => Array.from({ length: daysIn(y, m) }, (_, d) => new Date(Date.UTC(y, m, d + 1)).getUTCDay()).filter((x) => x === wd).length;

test("a month-end sheet on a closed day is due on the last working day before it, in its own month", () => {
  const master = masterRepository.get();
  assert.equal(workingDueDate("2026-12-31", master), "2026-12-30", "31-12-2026, a Thursday off: Wednesday 30-12");
  assert.equal(workingDueDate("2027-09-30", master), "2027-09-29");
  assert.equal(workingDueDate("2026-12-24", master), "2026-12-25", "mid-month: the next working day, as always");
});

test("every QC and HR document generated by its frequency, December 2026 to December 2027", () => {
  for (const [y, m] of MONTHS) ensureRecordsGeneratedForMonth(y, m, { isDemo: false });
  const docs = documentRepository.getRecordableUnscoped().filter((d) => ["QC", "HR"].includes(departmentOfDocument(d.id, d.formatNo) ?? ""));
  assert.ok(docs.length > 50, "the QC and HR documents");
  const seen: Record<string, number> = {};
  for (const d of docs) {
    const recs = recordRepository.queryUnscoped({ documentId: d.id, isDemo: false });
    const s = d.schedule;
    seen[s.type] = (seen[s.type] ?? 0) + 1;
    for (const [y, m] of MONTHS) {
      const n = recs.filter((r) => r.dueDate.slice(0, 7) === ym(y, m)).length;
      const at = `${d.formatNo} ${d.id} ${ym(y, m)}`;
      if (s.type === "as-required") assert.equal(n, 0, `${at}: made when it is needed`);
      else if (s.type === "daily") assert.ok(n >= 20 && n <= daysIn(y, m), `${at}: a sheet a working day (${n})`);
      else if (s.type === "weekly") assert.equal(n, weekdaysIn(y, m, s.weekday), `${at}: a sheet each week`);
      else if (s.type === "fortnightly") assert.equal(n, 2, `${at}: twice a month`);
      else if (s.type === "monthly") assert.equal(n, 1, `${at}: one a month`);
      else if (s.type === "yearly") {
        const inMonth = s.month === m;
        const want = inMonth ? (d.id.startsWith("qc-ruler-verification") ? 20 : 1) : 0;
        assert.equal(n, want, `${at}: once a year, in its month`);
      }
    }
  }
  for (const t of ["daily", "weekly", "fortnightly", "monthly", "yearly", "as-required"]) assert.ok(seen[t] > 0, `some ${t} documents`);
});
